template <bool B>
inline bool VerifyPart(::flatbuffers::VerifierTemplate<B> &verifier, const void *obj, Part type) {
  switch (type) {
    case Part::NONE: {
      return true;
    }
    case Part::Included_SharedThing: {
      auto ptr = reinterpret_cast<const UnrealTest::Included::SharedThing *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Part::Included_Cog: {
      auto ptr = reinterpret_cast<const UnrealTest::Included::Cog *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Part::Included_Vec2i: {
      return verifier.template VerifyField<UnrealTest::Included::Vec2i>(static_cast<const uint8_t *>(obj), 0, 4);
    }
    default: return true;
  }
}

template <bool B>
inline bool VerifyPartVector(::flatbuffers::VerifierTemplate<B> &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<Part> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyPart(
        verifier,  values->Get(i), types->GetEnum<Part>(i))) {
      return false;
    }
  }
  return true;
}

inline void *PartUnion::UnPack(const void *obj, Part type, const ::flatbuffers::resolver_function_t *resolver) {
  (void)resolver;
  switch (type) {
    case Part::Included_SharedThing: {
      auto ptr = reinterpret_cast<const UnrealTest::Included::SharedThing *>(obj);
      return ptr->UnPack(resolver);
    }
    case Part::Included_Cog: {
      auto ptr = reinterpret_cast<const UnrealTest::Included::Cog *>(obj);
      return ptr->UnPack(resolver);
    }
    case Part::Included_Vec2i: {
      auto ptr = reinterpret_cast<const UnrealTest::Included::Vec2i *>(obj);
      return new UnrealTest::Included::Vec2i(*ptr);
    }
    default: return nullptr;
  }
}

inline ::flatbuffers::Offset<void> PartUnion::Pack(::flatbuffers::FlatBufferBuilder &_fbb, const ::flatbuffers::rehasher_function_t *_rehasher) const {
  (void)_rehasher;
  switch (type) {
    case Part::Included_SharedThing: {
      auto ptr = reinterpret_cast<const UnrealTest::Included::SharedThingT *>(value);
      return CreateSharedThing(_fbb, ptr, _rehasher).Union();
    }
    case Part::Included_Cog: {
      auto ptr = reinterpret_cast<const UnrealTest::Included::CogT *>(value);
      return CreateCog(_fbb, ptr, _rehasher).Union();
    }
    case Part::Included_Vec2i: {
      auto ptr = reinterpret_cast<const UnrealTest::Included::Vec2i *>(value);
      return _fbb.CreateStruct(*ptr).Union();
    }
    default: return 0;
  }
}

inline PartUnion::PartUnion(const PartUnion &u) : type(u.type), value(nullptr) {
  switch (type) {
    case Part::Included_SharedThing: {
      value = new UnrealTest::Included::SharedThingT(*reinterpret_cast<UnrealTest::Included::SharedThingT *>(u.value));
      break;
    }
    case Part::Included_Cog: {
      value = new UnrealTest::Included::CogT(*reinterpret_cast<UnrealTest::Included::CogT *>(u.value));
      break;
    }
    case Part::Included_Vec2i: {
      value = new UnrealTest::Included::Vec2i(*reinterpret_cast<UnrealTest::Included::Vec2i *>(u.value));
      break;
    }
    default:
      break;
  }
}

inline void PartUnion::Reset() {
  switch (type) {
    case Part::Included_SharedThing: {
      auto ptr = reinterpret_cast<UnrealTest::Included::SharedThingT *>(value);
      delete ptr;
      break;
    }
    case Part::Included_Cog: {
      auto ptr = reinterpret_cast<UnrealTest::Included::CogT *>(value);
      delete ptr;
      break;
    }
    case Part::Included_Vec2i: {
      auto ptr = reinterpret_cast<UnrealTest::Included::Vec2i *>(value);
      delete ptr;
      break;
    }
    default: break;
  }
  value = nullptr;
  type = Part::NONE;
}

